// Reader RW5a: the TypeScript evaluator on the golden corpus (spec §8.2; G21, G22, G45).
//
// figureGoldenCorpus.json is generated by tests/figure_corpus.py and run by
// tests/test_figure_grammar.py too: both evaluators agree on every value
// within 1e-9 relative (1e-6 for integrals), on every accepted and rejected
// input, and on every panel's data.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import corpus from "./figureGoldenCorpus.json";
import {
  FigureGrammarError,
  checkNames,
  evaluate,
  parseExpression,
  type Definitions,
  type FigureNode,
} from "./figureGrammar";
import { compileSpec, evaluateFigure, expandedFree, type FigureSpec } from "./figureSpec";

type Encoded = number | string | null;
const decode = (value: Encoded): number | null =>
  typeof value === "string" ? ({ nan: NaN, inf: Infinity, "-inf": -Infinity } as Record<string, number>)[value] : value;

function close(actual: number | null, expected: number | null, tolerance: number): boolean {
  if (expected === null) return actual === null;
  if (actual === null) return false;
  if (Number.isNaN(expected)) return Number.isNaN(actual);
  if (!Number.isFinite(expected)) return actual === expected;
  return Math.abs(actual - expected) <= tolerance * Math.max(1, Math.abs(actual), Math.abs(expected));
}

function defsOf(definitions: Array<{ name: string; expr: string }>): Definitions {
  return new Map(definitions.map((definition) => [definition.name, parseExpression(definition.expr)] as [string, FigureNode]));
}

/** Every number in two panel outputs agrees (structure exactly). */
function sameData(actual: unknown, expected: unknown, tolerance: number, path = "$"): void {
  if (typeof expected === "number" || expected === null) {
    if (!close(actual as number | null, expected as number | null, tolerance)) {
      throw new Error(`${path}: ${String(actual)} != ${String(expected)}`);
    }
    return;
  }
  if (Array.isArray(expected)) {
    expect(Array.isArray(actual), path).toBe(true);
    expect((actual as unknown[]).length, path).toBe(expected.length);
    expected.forEach((item, index) => sameData((actual as unknown[])[index], item, tolerance, `${path}[${index}]`));
    return;
  }
  if (typeof expected === "object") {
    expect(Object.keys(actual as object).sort(), path).toEqual(Object.keys(expected as object).sort());
    for (const [key, item] of Object.entries(expected as object)) sameData((actual as Record<string, unknown>)[key], item, tolerance, `${path}.${key}`);
    return;
  }
  expect(actual, path).toEqual(expected);
}

const TOL = corpus.tolerance;

describe("expressions", () => {
  for (const item of corpus.expressions) {
    it(item.id, () => {
      const value = evaluate(parseExpression(item.expr), item.env as Record<string, number>, defsOf(item.definitions));
      expect(close(value, decode(item.expected as Encoded), item.integral ? TOL.integral : TOL.relative), `${item.expr}: ${value} vs ${String(item.expected)}`).toBe(true);
    });
  }
});

describe("rejected inputs", () => {
  for (const item of corpus.rejected) {
    it(item.id, () => {
      if (item.stage === "parse") {
        expect(() => parseExpression(item.expr)).toThrow(FigureGrammarError);
        return;
      }
      const node = parseExpression(item.expr);
      const defs = defsOf(item.definitions);
      expect(() => {
        checkNames(node, new Set(item.known), defs);
        const missing = [...expandedFree(node, defs)].filter((name) => !item.known.includes(name));
        if (missing.length) throw new FigureGrammarError(`unbound ${missing.join(",")}`);
      }).toThrow(FigureGrammarError);
    });
  }
});

describe("figures", () => {
  for (const item of corpus.figures) {
    it(item.id, () => {
      const compiled = compileSpec(item.spec as unknown as FigureSpec);
      item.params.forEach((params, index) => {
        sameData(evaluateFigure(compiled, params as Record<string, number>), item.expected[index], TOL.integral);
      });
      // Values with no integral or sum in them agree to 1e-9 too.
      const data = evaluateFigure(compiled, item.params[0] as Record<string, number>);
      data.panels.forEach((panel, index) => {
        const expected = item.expected[0].panels[index] as Record<string, unknown>;
        if (panel.kind === "linear_map_2d" || panel.kind === "pmf_bars") sameData(panel, expected, TOL.relative);
      });
    });
  }
  for (const item of corpus.rejected_figures) {
    it(`rejects ${item.id}`, () => {
      expect(() => compileSpec(item.spec as unknown as FigureSpec)).toThrow();
    });
  }
});

describe("fuzz", () => {
  it("agrees with the Python parser on every fuzz case", () => {
    const known = new Set([...corpus.fuzz.known, ...corpus.fuzz.bound]);
    for (const item of corpus.fuzz.cases) {
      let accepted = false;
      let value: number | null = null;
      try {
        const node = parseExpression(item.expr);
        checkNames(node, known, new Map());
        if ([...expandedFree(node, new Map())].some((name) => !corpus.fuzz.known.includes(name))) throw new FigureGrammarError("unbound");
        accepted = true;
        value = evaluate(node, corpus.fuzz.env);
      } catch (error) {
        if (!(error instanceof FigureGrammarError)) throw error;
      }
      expect(accepted, item.expr).toBe(item.accepted);
      if (accepted) expect(close(value, decode(item.expected as Encoded), 1e-12), item.expr).toBe(true);
    }
  });

  it("refuses random text cleanly or parses it (never another error)", () => {
    let seed = 7;
    const random = () => {
      seed = (seed * 1103515245 + 12345) % 2147483648;
      return seed / 2147483648;
    };
    const alphabet = Array.from({ length: 95 }, (_, i) => String.fromCharCode(32 + i)).concat(["é", "٣", " ", "\n", "\t"]);
    for (let n = 0; n < 4000; n += 1) {
      const text = Array.from({ length: Math.floor(random() * 25) }, () => alphabet[Math.floor(random() * alphabet.length)]).join("");
      try {
        evaluate(parseExpression(text), {});
      } catch (error) {
        expect(error).toBeInstanceOf(FigureGrammarError);
      }
    }
  });
});

describe("G45: the two-sided exponential", () => {
  it("P(X ≤ 0) = p whatever λ is, within 1e-6 of Python's integration", () => {
    const flagship = corpus.figures.find((item) => item.id === "two_sided_exponential");
    const compiled = compileSpec(flagship!.spec as unknown as FigureSpec);
    for (const p of [0.05, 0.3, 0.6, 0.95]) {
      for (const lam of [0.5, 1, 2, 4]) {
        const data = evaluateFigure(compiled, { p, lam });
        const readout = data.panels[1];
        if (readout.kind !== "readout") throw new Error("panel 2 is the readout");
        expect(Math.abs((readout.value ?? NaN) - p * (1 - Math.exp(-lam * 40)))).toBeLessThanOrEqual(1e-6);
      }
    }
    const python = corpus.expressions.filter((item) => item.id.startsWith("two_sided_P_le_0"));
    expect(python.length).toBe(9);
    for (const item of python) {
      const data = evaluateFigure(compiled, item.env as Record<string, number>);
      const readout = data.panels[1];
      if (readout.kind !== "readout") throw new Error("panel 2 is the readout");
      expect(Math.abs((readout.value ?? NaN) - (decode(item.expected as Encoded) as number))).toBeLessThanOrEqual(1e-6);
    }
  });
});

it("G21 lint: nothing in the figure renderer builds or runs code from text", () => {
  const files = ["figureGrammar.ts", "figureSpec.ts", "FigureInline.tsx", "FigurePanels.tsx", "useFigures.ts"];
  for (const file of files) {
    let source = "";
    try {
      source = readFileSync(join(__dirname, file), "utf8");
    } catch {
      continue;
    }
    for (const banned of [/\beval\s*\(/, /\bnew\s+Function\b/, /\bFunction\s*\(/, /set(?:Timeout|Interval)\s*\(\s*["'`]/, /dangerouslySetInnerHTML/, /\binnerHTML\b/]) {
      expect(banned.test(source), `${file} matches ${banned}`).toBe(false);
    }
  }
});
